// Voxel HUD portraits: client/src/art/portraits/<short>.js (generated by tools/vox/portrait.mjs) replaces the sheet's painted 'portrait' frame.
//   withVoxPortrait(short, def) -> Promise<def>   swaps in place (idempotent) unless `?vox=0`; the painted frame stays in the sheet module
//     def missing (hero without a 2D sheet) -> a portrait-only def { portraitOnly: true } (atlas.hasSheet ignores it, so body stand-ins still apply)
//   portraitShorts() -> heroes with a voxel portrait asset
// The voxel portrait is rendered at the 32x42 the HUD shows (1 art px = 1 u), so nearest sampling stays crisp at every integer HUD scale.
// Sheet frames share one palette keyed by a single char, so the portrait's chars are shifted by PAL_SHIFT (no clash with the sheet's own).
// def.faceCrop = [x, y, w, h] of the face in portrait px (set with the swap; consumers fall back to the painted 24x24 crop).
let mods = {};
try { mods = import.meta.glob('./portraits/*.js'); } catch { /* not running under vite (node tests) */ }

// Same switch as voxEnabled in render/voxactors.js (not imported: that module pulls the whole 3D renderer into the lobby / node tests).
const voxOn = typeof location === 'undefined' || new URLSearchParams(location.search).get('vox') !== '0';
const PAL_SHIFT = 0x100;
const shift = (c) => String.fromCharCode(c.charCodeAt(0) + PAL_SHIFT);

export const portraitShorts = () => Object.keys(mods).map((p) => p.slice(p.lastIndexOf('/') + 1).replace(/\.js$/, ''));

export async function withVoxPortrait(short, def) {
  if (!voxOn || (def && (!def.frames || def.faceCrop))) return def;
  const load = mods['./portraits/' + short + '.js'];
  if (!load) return def;
  try {
    const p = (await load()).default;
    if (!p || !p.rows || (def && def.faceCrop)) return def;
    def = def || { pal: {}, anchor: [0, 0], frames: {}, portraitOnly: true };
    for (const c in p.pal) def.pal[shift(c)] = p.pal[c];
    def.frames.portrait = p.rows.map((r) => Array.from(r, shift).join(''));
    def.faceCrop = p.face;
  } catch (e) { console.warn('[portraits] "' + short + '" failed to load:', e && e.message); }
  return def;
}
